const fs = require('fs'), path = require('path')
const files = {}

files["supabase/migrations/008_availability.sql"] = "-- ============================================================\n-- FYP.STUDIO — Disponibilidad avanzada barbería\n-- Ejecutar DESPUÉS de 007_calendar.sql\n-- ============================================================\n\n-- ── Horarios semanales por staff ──────────────────────────────\n-- (ya existe staff_schedules de 005, la extendemos)\nalter table staff_schedules\n  add column if not exists break_start time,\n  add column if not exists break_end   time;\n\n-- Si no existía la tabla, crearla completa\ncreate table if not exists staff_schedules (\n  id           uuid primary key default uuid_generate_v4(),\n  staff_id     uuid not null references staff(id) on delete cascade,\n  business_id  uuid not null references businesses(id) on delete cascade,\n  day_of_week  int  not null check (day_of_week between 0 and 6),\n  is_working   boolean not null default true,\n  start_time   time not null default '09:00',\n  end_time     time not null default '19:00',\n  break_start  time,\n  break_end    time,\n  unique(staff_id, day_of_week)\n);\n\ncreate index if not exists idx_schedules_staff    on staff_schedules(staff_id);\ncreate index if not exists idx_schedules_business on staff_schedules(business_id);\n\nalter table staff_schedules enable row level security;\n\ncreate policy \"comercio gestiona staff_schedules\"\n  on staff_schedules for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\ncreate policy \"publico lee staff_schedules\"\n  on staff_schedules for select using (true);\n\n-- ── Bloqueos extendidos ───────────────────────────────────────\n-- Ampliar blocked_slots para rangos de fechas\nalter table blocked_slots\n  add column if not exists date_from date,  -- para rango\n  add column if not exists date_to   date,  -- para rango\n  add column if not exists time_from time,  -- para rango horario\n  add column if not exists time_to   time;  -- para rango horario\n\n-- Vista que expande rangos en días individuales (útil para queries)\ncreate or replace view v_blocked_days as\n  select\n    b.id,\n    b.business_id,\n    b.staff_id,\n    d::date as date,\n    b.time_slot,\n    b.time_from,\n    b.time_to,\n    b.reason\n  from blocked_slots b\n  cross join generate_series(\n    coalesce(b.date_from, b.date),\n    coalesce(b.date_to,   b.date),\n    '1 day'::interval\n  ) as d\n  where b.date is not null or b.date_from is not null;\n\n-- ── Días cerrados globales del negocio ────────────────────────\ncreate table if not exists business_closed_days (\n  id          uuid primary key default uuid_generate_v4(),\n  business_id uuid not null references businesses(id) on delete cascade,\n  date        date,\n  date_from   date,\n  date_to     date,\n  reason      text,\n  created_at  timestamptz not null default now()\n);\n\ncreate index if not exists idx_closed_business on business_closed_days(business_id);\nalter table business_closed_days enable row level security;\n\ncreate policy \"comercio gestiona closed_days\"\n  on business_closed_days for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\ncreate policy \"publico lee closed_days\"\n  on business_closed_days for select using (true);\n\nalter publication supabase_realtime add table business_closed_days;\n"

files["types/index.ts"] = "export type Plan = 'basic' | 'pro' | 'premium'\nexport type SubscriptionStatus = 'trial' | 'active' | 'past_due' | 'canceled' | 'suspended'\nexport type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\nexport type PaymentStatus = 'unpaid' | 'paid' | 'refunded'\nexport type DeliveryType = 'delivery' | 'pickup'\nexport type UserRole = 'owner' | 'staff' | 'superadmin'\nexport type AIGenerationType = 'product' | 'promo' | 'insights'\n\nexport interface Business {\n  id: string; name: string; slug: string; description?: string | null\n  logo_url?: string | null; banner_url?: string | null; whatsapp?: string | null\n  address?: string | null; currency: string; primary_color: string\n  secondary_color: string; plan: Plan; active: boolean\n  subscription_status: SubscriptionStatus; subscription_expires_at?: string | null\n  instagram?: string | null; facebook?: string | null; tiktok?: string | null\n  website?: string | null; vertical_type?: string | null; enabled_modules?: string[] | null; created_at: string; updated_at: string\n}\n\nexport interface Profile {\n  id: string; user_id: string; business_id: string\n  role: UserRole; created_at: string; business?: Business\n}\n\nexport interface Category {\n  id: string; business_id: string; name: string; slug: string\n  sort_order: number; active: boolean; created_at: string\n}\n\nexport interface Product {\n  id: string; business_id: string; category_id?: string | null\n  name: string; slug: string; description?: string | null; price: number\n  images: string[]; tags: string[]; stock?: number | null; featured: boolean\n  active: boolean; seo_title?: string | null; seo_desc?: string | null\n  created_at: string; updated_at: string; category?: Category | null\n}\n\nexport interface Customer {\n  id: string; business_id: string; name: string; phone?: string | null\n  address?: string | null; email?: string | null; total_orders: number\n  total_spent: number; created_at: string; updated_at: string\n}\n\nexport interface Order {\n  id: string; business_id: string; customer_id?: string | null\n  order_number: number; status: OrderStatus; payment_status: PaymentStatus\n  confirmed_sale: boolean; delivery_type: DeliveryType; subtotal: number\n  total: number; comment?: string | null; customer_name: string\n  customer_phone?: string | null; customer_address?: string | null\n  created_at: string; updated_at: string; items?: OrderItem[]; customer?: Customer | null\n}\n\nexport interface OrderItem {\n  id: string; order_id: string; product_id?: string | null\n  product_name: string; unit_price: number; quantity: number; subtotal: number\n  product?: Product | null\n}\n\nexport interface CartItem { product: Product; quantity: number }\n\nexport interface CheckoutFormData {\n  name: string; phone: string; address?: string\n  delivery_type: DeliveryType; comment?: string\n}\n\nexport interface CreateOrderResponse { orderId: string; orderNumber: number }\n\nexport interface AIProductOutput {\n  name: string; description: string; category: string; tags: string[]\n  instagram_copy: string; whatsapp_copy: string; hashtags: string[]\n  seo_title: string; seo_description: string\n}\n\nexport interface AIPromoOutput {\n  title: string; body: string; instagram_story: string\n  whatsapp_message: string; cta: string\n}\n\nexport interface DashboardStats {\n  pendingOrders: number; confirmedOrders: number; totalRevenue: number\n  todayRevenue: number; totalProducts: number; totalCustomers: number\n  recentOrders: Order[]; topProducts: { name: string; count: number; revenue: number }[]\n  cancelRate?: number\n}\n\n// ── Inventario ────────────────────────────────────────────────\n\nexport interface InventoryCategory {\n  id: string\n  business_id: string\n  name: string\n  color: string\n  icon: string\n  created_at: string\n}\n\nexport type MovementType = 'entrada' | 'salida' | 'ajuste' | 'devolucion'\n\nexport interface InventoryItem {\n  id: string\n  business_id: string\n  category_id?: string | null\n  product_id?: string | null\n  name: string\n  sku?: string | null\n  unit: string\n  stock_current: number\n  stock_min: number\n  stock_max?: number | null\n  cost_price?: number | null\n  supplier?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // joins\n  category?: InventoryCategory | null\n  product?: { name: string } | null\n}\n\nexport interface InventoryMovement {\n  id: string\n  business_id: string\n  item_id: string\n  order_id?: string | null\n  type: MovementType\n  quantity: number\n  stock_before: number\n  stock_after: number\n  reason?: string | null\n  created_by?: string | null\n  created_at: string\n  item?: InventoryItem | null\n}\n\nexport type StockStatus = 'ok' | 'low' | 'critical' | 'out'\n\nexport function getStockStatus(item: InventoryItem): StockStatus {\n  if (item.stock_current <= 0) return 'out'\n  if (item.stock_current <= item.stock_min * 0.5) return 'critical'\n  if (item.stock_current <= item.stock_min) return 'low'\n  return 'ok'\n}\n\n// ── Proveedores ───────────────────────────────────────────────\n\nexport interface Supplier {\n  id: string\n  business_id: string\n  name: string\n  contact_name?: string | null\n  phone?: string | null\n  email?: string | null\n  address?: string | null\n  city?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // computed\n  products?: SupplierProduct[]\n}\n\nexport interface SupplierProduct {\n  id: string\n  supplier_id: string\n  business_id: string\n  inventory_item_id?: string | null\n  product_name: string\n  sku_supplier?: string | null\n  unit: string\n  price?: number | null\n  min_order?: number | null\n  lead_days?: number | null\n  notes?: string | null\n  created_at: string\n  updated_at: string\n  // join\n  inventory_item?: { name: string } | null\n}\n\n// ── Barbería / Belleza ────────────────────────────────────────\n\nexport interface Branch {\n  id: string\n  business_id: string\n  name: string\n  address?: string | null\n  phone?: string | null\n  whatsapp?: string | null\n  city?: string | null\n  is_main: boolean\n  active: boolean\n  created_at: string\n}\n\nexport interface Staff {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  name: string\n  role: string\n  bio?: string | null\n  avatar_url?: string | null\n  phone?: string | null\n  color: string\n  active: boolean\n  created_at: string\n  updated_at: string\n  branch?: Branch | null\n}\n\nexport interface StaffSchedule {\n  id: string\n  staff_id: string\n  business_id: string\n  day_of_week: number  // 0=Dom, 1=Lun, 2=Mar...\n  start_time: string   // '09:00'\n  end_time: string     // '18:00'\n  break_start?: string | null\n  break_end?: string | null\n  is_working: boolean\n}\n\nexport type BookingStatus = 'pending' | 'confirmed' | 'done' | 'cancelled' | 'noshow'\n\nexport interface Booking {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  staff_id?: string | null\n  product_id?: string | null\n  customer_name: string\n  customer_phone?: string | null\n  customer_email?: string | null\n  date: string         // 'YYYY-MM-DD'\n  start_time: string   // 'HH:MM'\n  end_time: string\n  duration_min: number\n  status: BookingStatus\n  notes?: string | null\n  price?: number | null\n  source: string\n  created_at: string\n  updated_at: string\n  // joins\n  staff?: Staff | null\n  branch?: Branch | null\n  product?: { name: string; price: number } | null\n}\n\n// Page Builder\nexport interface PageConfig {\n  theme: {\n    primaryColor: string\n    secondaryColor: string\n    bgColor: string\n    textColor: string\n    font: string\n    borderRadius: 'none' | 'sm' | 'md' | 'lg' | 'full'\n    style: 'modern' | 'minimal' | 'bold' | 'elegant'\n  }\n  hero: {\n    enabled: boolean\n    title: string\n    subtitle: string\n    ctaText: string\n    ctaAction: 'book' | 'whatsapp' | 'scroll'\n    backgroundType: 'color' | 'image' | 'gradient'\n    backgroundValue: string\n  }\n  sections: PageSection[]\n}\n\nexport interface PageSection {\n  id: string\n  type: 'services' | 'team' | 'gallery' | 'testimonials' | 'contact' | 'hours' | 'promo'\n  enabled: boolean\n  title: string\n  order: number\n}\n\n// ── Gastronomía ───────────────────────────────────────────────\n\nexport interface BusinessHours {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  day_of_week: number\n  is_open: boolean\n  open_time: string\n  close_time: string\n}\n\nexport interface Combo {\n  id: string\n  business_id: string\n  name: string\n  description?: string | null\n  price: number\n  image_url?: string | null\n  active: boolean\n  featured: boolean\n  valid_from?: string | null\n  valid_until?: string | null\n  created_at: string\n  items?: ComboItem[]\n}\n\nexport interface ComboItem {\n  id: string\n  combo_id: string\n  product_id?: string | null\n  product_name: string\n  quantity: number\n}\n\nexport type KitchenStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\n\nexport const KITCHEN_FLOW: KitchenStatus[] = [\n  'pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered'\n]\n\n// ── Calendario avanzado ───────────────────────────────────────\n\nexport interface BlockedSlot {\n  id: string\n  business_id: string\n  staff_id?: string | null\n  branch_id?: string | null\n  date: string         // 'YYYY-MM-DD'\n  time_slot?: string | null  // null = día completo\n  reason?: string | null\n  created_at: string\n}\n\n// ── Disponibilidad ────────────────────────────────────────────\n\nexport interface StaffScheduleFull {\n  id?: string\n  staff_id: string\n  business_id: string\n  day_of_week: number\n  is_working: boolean\n  start_time: string\n  end_time: string\n  break_start?: string | null\n  break_end?: string | null\n}\n\nexport interface BlockedRange {\n  id: string\n  business_id: string\n  staff_id?: string | null\n  date?: string | null\n  date_from?: string | null\n  date_to?: string | null\n  time_slot?: string | null\n  time_from?: string | null\n  time_to?: string | null\n  reason?: string | null\n  created_at: string\n}\n\nexport interface ClosedDay {\n  id: string\n  business_id: string\n  date?: string | null\n  date_from?: string | null\n  date_to?: string | null\n  reason?: string | null\n  created_at: string\n}\n"

files["app/admin/barbershop/AvailabilityTab.tsx"] = "// app/admin/barbershop/AvailabilityTab.tsx\n'use client'\nimport { useState, useEffect } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  Clock, Calendar, Plus, X, Check, Loader2, Lock,\n  ChevronDown, User, AlertTriangle, Unlock, Trash2,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport type { Staff, StaffScheduleFull, BlockedRange, ClosedDay } from '@/types'\n\nconst DAYS      = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']\nconst DAYS_S    = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst REASONS   = ['Feriado','Vacaciones','Cerrado','Agenda llena','Personal','Otro']\n\ninterface Props {\n  businessId: string\n  staff: Staff[]\n  primaryColor: string\n}\n\nexport default function AvailabilityTab({ businessId, staff, primaryColor }: Props) {\n  const supabase = createClient()\n  const color = primaryColor\n\n  // Sub-tab\n  const [subTab, setSubTab] = useState<'schedules'|'blocks'>('schedules')\n\n  // ── SCHEDULES ──\n  const [selectedStaff, setSelectedStaff] = useState<Staff|null>(staff[0]??null)\n  const [schedules, setSchedules] = useState<StaffScheduleFull[]>([])\n  const [loadingSchedules, setLoadingSchedules] = useState(false)\n  const [savingDay, setSavingDay] = useState<number|null>(null)\n\n  useEffect(() => {\n    if (!selectedStaff) return\n    setLoadingSchedules(true)\n    supabase\n      .from('staff_schedules')\n      .select('*')\n      .eq('staff_id', selectedStaff.id)\n      .then(({ data }) => {\n        // Completar con todos los días si faltan\n        const existing = data ?? []\n        const full = Array.from({ length: 7 }, (_, i) => {\n          const found = existing.find((s: StaffScheduleFull) => s.day_of_week === i)\n          return found ?? {\n            staff_id:    selectedStaff.id,\n            business_id: businessId,\n            day_of_week: i,\n            is_working:  i >= 1 && i <= 6, // Lun-Sáb por defecto\n            start_time:  '09:00',\n            end_time:    '19:00',\n            break_start: null,\n            break_end:   null,\n          } as StaffScheduleFull\n        })\n        setSchedules(full)\n        setLoadingSchedules(false)\n      })\n  }, [selectedStaff])\n\n  function updateSchedule(dayOfWeek: number, field: keyof StaffScheduleFull, value: unknown) {\n    setSchedules(prev => prev.map(s =>\n      s.day_of_week === dayOfWeek ? { ...s, [field]: value } : s\n    ))\n  }\n\n  async function saveSchedule(s: StaffScheduleFull) {\n    setSavingDay(s.day_of_week)\n    if (s.id) {\n      await supabase.from('staff_schedules').update({\n        is_working: s.is_working,\n        start_time: s.start_time,\n        end_time:   s.end_time,\n        break_start:s.break_start || null,\n        break_end:  s.break_end   || null,\n      }).eq('id', s.id)\n    } else {\n      const { data } = await supabase.from('staff_schedules').insert({\n        staff_id:    s.staff_id,\n        business_id: businessId,\n        day_of_week: s.day_of_week,\n        is_working:  s.is_working,\n        start_time:  s.start_time,\n        end_time:    s.end_time,\n        break_start: s.break_start || null,\n        break_end:   s.break_end   || null,\n      }).select('*').single()\n      if (data) {\n        setSchedules(prev => prev.map(sc =>\n          sc.day_of_week === s.day_of_week ? { ...sc, id: (data as StaffScheduleFull).id } : sc\n        ))\n      }\n    }\n    setSavingDay(null)\n  }\n\n  async function saveAllSchedules() {\n    for (const s of schedules) {\n      await saveSchedule(s)\n    }\n  }\n\n  // ── BLOCKS ──\n  const [blocks,     setBlocks]     = useState<BlockedRange[]>([])\n  const [closedDays, setClosedDays] = useState<ClosedDay[]>([])\n  const [loadingBlocks, setLoadingBlocks] = useState(false)\n\n  // Modal bloqueo\n  const [showModal,   setShowModal]   = useState(false)\n  const [blockType,   setBlockType]   = useState<'day'|'range'|'time'>('day')\n  const [blockTarget, setBlockTarget] = useState<'business'|'staff'>('business')\n  const [blockStaffId, setBlockStaffId] = useState(staff[0]?.id ?? '')\n  const [blockDate,   setBlockDate]   = useState('')\n  const [blockFrom,   setBlockFrom]   = useState('')\n  const [blockTo,     setBlockTo]     = useState('')\n  const [blockTimeFrom, setBlockTimeFrom] = useState('')\n  const [blockTimeTo,   setBlockTimeTo]   = useState('')\n  const [blockReason, setBlockReason] = useState('Feriado')\n  const [blockSaving, setBlockSaving] = useState(false)\n\n  useEffect(() => {\n    setLoadingBlocks(true)\n    const future = new Date().toISOString().split('T')[0]\n    Promise.all([\n      supabase.from('blocked_slots')\n        .select('*').eq('business_id', businessId)\n        .or(`date.gte.${future},date_from.gte.${future}`)\n        .order('date', { nullsFirst: false })\n        .order('date_from', { nullsFirst: false }),\n      supabase.from('business_closed_days')\n        .select('*').eq('business_id', businessId)\n        .order('date', { nullsFirst: false }),\n    ]).then(([b, c]) => {\n      setBlocks((b.data ?? []) as BlockedRange[])\n      setClosedDays((c.data ?? []) as ClosedDay[])\n      setLoadingBlocks(false)\n    })\n  }, [])\n\n  async function addBlock() {\n    setBlockSaving(true)\n    try {\n      if (blockTarget === 'business') {\n        // Cerrar todo el negocio\n        const { data } = await supabase.from('business_closed_days').insert({\n          business_id: businessId,\n          date:      blockType === 'day'   ? blockDate : null,\n          date_from: blockType === 'range' ? blockFrom : null,\n          date_to:   blockType === 'range' ? blockTo   : null,\n          reason:    blockReason,\n        }).select('*').single()\n        if (data) setClosedDays(prev => [...prev, data as ClosedDay])\n      } else {\n        // Bloquear para barbero específico\n        const { data } = await supabase.from('blocked_slots').insert({\n          business_id: businessId,\n          staff_id:    blockStaffId || null,\n          date:        blockType === 'day'  ? blockDate : null,\n          date_from:   blockType === 'range'? blockFrom : null,\n          date_to:     blockType === 'range'? blockTo   : null,\n          time_slot:   blockType === 'time' && blockTimeFrom && !blockTimeTo ? blockTimeFrom : null,\n          time_from:   blockType === 'time' ? blockTimeFrom : null,\n          time_to:     blockType === 'time' ? blockTimeTo   : null,\n          reason:      blockReason,\n        }).select('*').single()\n        if (data) setBlocks(prev => [...prev, data as BlockedRange])\n      }\n      setShowModal(false)\n      resetModal()\n    } catch(e) { console.error(e) }\n    setBlockSaving(false)\n  }\n\n  function resetModal() {\n    setBlockDate(''); setBlockFrom(''); setBlockTo('')\n    setBlockTimeFrom(''); setBlockTimeTo(''); setBlockReason('Feriado')\n    setBlockType('day'); setBlockTarget('business')\n  }\n\n  async function removeBlock(id: string, table: 'blocked_slots'|'business_closed_days') {\n    await supabase.from(table).delete().eq('id', id)\n    if (table === 'blocked_slots')\n      setBlocks(prev => prev.filter(b => b.id !== id))\n    else\n      setClosedDays(prev => prev.filter(c => c.id !== id))\n  }\n\n  function formatBlockDate(b: BlockedRange | ClosedDay) {\n    if ('date' in b && b.date) return b.date\n    if ('date_from' in b && b.date_from) return `${b.date_from} → ${b.date_to}`\n    if ('time_from' in (b as BlockedRange) && (b as BlockedRange).time_from)\n      return `${(b as BlockedRange).time_from} — ${(b as BlockedRange).time_to}`\n    return '—'\n  }\n\n  const today = new Date().toISOString().split('T')[0]\n\n  return (\n    <div className=\"space-y-4\">\n\n      {/* Sub-tabs */}\n      <div className=\"flex items-center gap-1 bg-gray-100 rounded-xl p-1 w-fit\">\n        {([\n          { key: 'schedules', label: 'Horarios por barbero', icon: Clock    },\n          { key: 'blocks',    label: 'Bloqueos',             icon: Lock     },\n        ] as { key:'schedules'|'blocks'; label:string; icon:React.ElementType }[]).map(({ key, label, icon: Icon }) => (\n          <button key={key} onClick={() => setSubTab(key)}\n            className={cn('flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium transition-all',\n              subTab === key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700')}>\n            <Icon size={13} />{label}\n          </button>\n        ))}\n      </div>\n\n      {/* ── HORARIOS POR BARBERO ── */}\n      {subTab === 'schedules' && (\n        <div className=\"space-y-4\">\n          {/* Selector de barbero */}\n          <div className=\"bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden\">\n            <div className=\"px-4 py-3 border-b border-gray-100 bg-gray-50/50\">\n              <p className=\"text-xs font-semibold text-gray-600 mb-2\">Seleccioná el barbero</p>\n              <div className=\"flex flex-wrap gap-2\">\n                {staff.map(s => (\n                  <button key={s.id} onClick={() => setSelectedStaff(s)}\n                    className={cn('flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-semibold transition-all',\n                      selectedStaff?.id === s.id ? 'text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200')}\n                    style={selectedStaff?.id === s.id ? { background: s.color || color } : {}}>\n                    <div className=\"h-5 w-5 rounded-full flex items-center justify-center text-white text-[9px] font-black shrink-0\"\n                      style={{ background: s.color || color }}>\n                      {s.name.slice(0,1)}\n                    </div>\n                    {s.name}\n                  </button>\n                ))}\n              </div>\n            </div>\n\n            {/* Horarios del barbero */}\n            {selectedStaff && !loadingSchedules && (\n              <div className=\"divide-y divide-gray-50\">\n                {schedules.map(s => (\n                  <div key={s.day_of_week} className=\"px-4 py-3\">\n                    {/* Fila principal */}\n                    <div className=\"flex items-center gap-3\">\n                      {/* Toggle trabaja */}\n                      <button onClick={() => updateSchedule(s.day_of_week, 'is_working', !s.is_working)}\n                        className={cn('relative h-5 w-9 rounded-full transition-colors shrink-0',\n                          s.is_working ? 'bg-green-500' : 'bg-gray-200')}>\n                        <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n                          s.is_working ? 'left-4' : 'left-0.5')}/>\n                      </button>\n\n                      {/* Día */}\n                      <p className={cn('text-sm font-bold w-9 shrink-0',\n                        s.is_working ? 'text-gray-900' : 'text-gray-400')}>\n                        {DAYS_S[s.day_of_week]}\n                      </p>\n\n                      {s.is_working ? (\n                        <div className=\"flex items-center gap-2 flex-1 flex-wrap\">\n                          <div className=\"flex items-center gap-1.5\">\n                            <input type=\"time\" value={s.start_time}\n                              onChange={e => updateSchedule(s.day_of_week, 'start_time', e.target.value)}\n                              className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs w-24\"/>\n                            <span className=\"text-xs text-gray-400\">a</span>\n                            <input type=\"time\" value={s.end_time}\n                              onChange={e => updateSchedule(s.day_of_week, 'end_time', e.target.value)}\n                              className=\"rounded-xl border border-gray-200 px-2 py-1.5 text-xs w-24\"/>\n                          </div>\n                        </div>\n                      ) : (\n                        <p className=\"text-xs text-gray-400 flex-1\">No trabaja</p>\n                      )}\n\n                      {/* Guardar día */}\n                      <button onClick={() => saveSchedule(s)}\n                        disabled={savingDay === s.day_of_week}\n                        className=\"flex h-7 w-7 items-center justify-center rounded-lg text-white shrink-0 disabled:opacity-40\"\n                        style={{ background: color }}>\n                        {savingDay === s.day_of_week\n                          ? <Loader2 size={11} className=\"animate-spin\"/>\n                          : <Check size={11}/>}\n                      </button>\n                    </div>\n\n                    {/* Descanso — expandible */}\n                    {s.is_working && (\n                      <div className=\"ml-[52px] mt-2 flex items-center gap-2 flex-wrap\">\n                        <span className=\"text-[10px] text-gray-400 shrink-0\">Descanso:</span>\n                        <input type=\"time\" value={s.break_start ?? ''}\n                          onChange={e => updateSchedule(s.day_of_week, 'break_start', e.target.value)}\n                          placeholder=\"--:--\"\n                          className=\"rounded-xl border border-gray-200 px-2 py-1 text-xs w-20\"/>\n                        <span className=\"text-[10px] text-gray-400\">a</span>\n                        <input type=\"time\" value={s.break_end ?? ''}\n                          onChange={e => updateSchedule(s.day_of_week, 'break_end', e.target.value)}\n                          placeholder=\"--:--\"\n                          className=\"rounded-xl border border-gray-200 px-2 py-1 text-xs w-20\"/>\n                        {s.break_start && (\n                          <button onClick={() => {\n                            updateSchedule(s.day_of_week, 'break_start', null)\n                            updateSchedule(s.day_of_week, 'break_end', null)\n                          }} className=\"text-[10px] text-gray-400 hover:text-red-500\">\n                            <X size={11}/>\n                          </button>\n                        )}\n                      </div>\n                    )}\n                  </div>\n                ))}\n              </div>\n            )}\n\n            {loadingSchedules && (\n              <div className=\"flex justify-center py-8\">\n                <Loader2 size={20} className=\"animate-spin text-gray-300\"/>\n              </div>\n            )}\n\n            {/* Guardar todos */}\n            {selectedStaff && !loadingSchedules && (\n              <div className=\"px-4 py-3 border-t border-gray-100 bg-gray-50/50\">\n                <button onClick={saveAllSchedules}\n                  className=\"flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-semibold text-white\"\n                  style={{ background: color }}>\n                  <Check size={14}/> Guardar todos los horarios\n                </button>\n                <p className=\"text-xs text-gray-400 mt-2\">\n                  Los días marcados como \"No trabaja\" no aparecerán disponibles en la tienda\n                </p>\n              </div>\n            )}\n          </div>\n\n          {/* Preview rápido */}\n          {selectedStaff && schedules.some(s => s.is_working) && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n              <p className=\"text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide\">\n                Resumen — {selectedStaff.name}\n              </p>\n              <div className=\"flex flex-wrap gap-2\">\n                {schedules.map(s => (\n                  <div key={s.day_of_week}\n                    className={cn('rounded-xl px-3 py-2 text-center',\n                      s.is_working ? 'text-white' : 'bg-gray-100 text-gray-400')}\n                    style={s.is_working ? { background: color } : {}}>\n                    <p className=\"text-[10px] font-bold\">{DAYS_S[s.day_of_week]}</p>\n                    {s.is_working && (\n                      <p className=\"text-[9px] opacity-80 mt-0.5\">\n                        {s.start_time.slice(0,5)}–{s.end_time.slice(0,5)}\n                      </p>\n                    )}\n                    {!s.is_working && <p className=\"text-[9px]\">—</p>}\n                  </div>\n                ))}\n              </div>\n            </div>\n          )}\n        </div>\n      )}\n\n      {/* ── BLOQUEOS ── */}\n      {subTab === 'blocks' && (\n        <div className=\"space-y-4\">\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-sm text-gray-500\">\n              {blocks.length + closedDays.length} bloqueos activos\n            </p>\n            <button onClick={() => setShowModal(true)}\n              className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-xs font-semibold text-white\"\n              style={{ background: '#DC2626' }}>\n              <Plus size={13}/> Nuevo bloqueo\n            </button>\n          </div>\n\n          {/* Lista bloqueos negocio */}\n          {closedDays.length > 0 && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden\">\n              <div className=\"px-4 py-2.5 border-b border-gray-100 bg-red-50/50\">\n                <p className=\"text-xs font-bold text-red-700 flex items-center gap-1.5\">\n                  <Lock size={12}/> Todo el negocio cerrado\n                </p>\n              </div>\n              {closedDays.map(c => (\n                <div key={c.id} className=\"flex items-center gap-3 px-4 py-3 border-b border-gray-50 last:border-0\">\n                  <div className=\"flex-1\">\n                    <p className=\"text-sm font-semibold text-gray-900\">{formatBlockDate(c)}</p>\n                    {c.reason && <p className=\"text-xs text-gray-500\">{c.reason}</p>}\n                  </div>\n                  <button onClick={() => removeBlock(c.id, 'business_closed_days')}\n                    className=\"flex h-7 w-7 items-center justify-center rounded-lg text-gray-400 hover:bg-red-50 hover:text-red-500\">\n                    <Trash2 size={13}/>\n                  </button>\n                </div>\n              ))}\n            </div>\n          )}\n\n          {/* Lista bloqueos por barbero */}\n          {blocks.length > 0 && (\n            <div className=\"bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden\">\n              <div className=\"px-4 py-2.5 border-b border-gray-100 bg-amber-50/50\">\n                <p className=\"text-xs font-bold text-amber-700 flex items-center gap-1.5\">\n                  <User size={12}/> Bloqueos por barbero / horario\n                </p>\n              </div>\n              {blocks.map(b => {\n                const staffName = staff.find(s => s.id === b.staff_id)?.name\n                return (\n                  <div key={b.id} className=\"flex items-center gap-3 px-4 py-3 border-b border-gray-50 last:border-0\">\n                    <div className=\"flex-1\">\n                      <div className=\"flex items-center gap-2\">\n                        <p className=\"text-sm font-semibold text-gray-900\">{formatBlockDate(b)}</p>\n                        {staffName && (\n                          <span className=\"badge bg-gray-100 text-gray-600 text-[10px]\">\n                            ✂️ {staffName}\n                          </span>\n                        )}\n                        {!staffName && (\n                          <span className=\"badge bg-blue-50 text-blue-600 text-[10px]\">Todos</span>\n                        )}\n                      </div>\n                      {b.reason && <p className=\"text-xs text-gray-500\">{b.reason}</p>}\n                    </div>\n                    <button onClick={() => removeBlock(b.id, 'blocked_slots')}\n                      className=\"flex h-7 w-7 items-center justify-center rounded-lg text-gray-400 hover:bg-red-50 hover:text-red-500\">\n                      <Trash2 size={13}/>\n                    </button>\n                  </div>\n                )\n              })}\n            </div>\n          )}\n\n          {blocks.length === 0 && closedDays.length === 0 && (\n            <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-12 text-center\">\n              <Unlock size={24} className=\"mx-auto text-gray-200 mb-2\"/>\n              <p className=\"text-sm text-gray-400\">Sin bloqueos activos</p>\n              <p className=\"text-xs text-gray-300 mt-1\">\n                Todo está disponible para reservas\n              </p>\n            </div>\n          )}\n\n          {/* Tip */}\n          <div className=\"rounded-2xl bg-blue-50 border border-blue-100 px-4 py-3.5\">\n            <p className=\"text-xs font-semibold text-blue-800 mb-1\">💡 Cómo funciona</p>\n            <ul className=\"text-xs text-blue-700 space-y-1\">\n              <li>• <strong>Negocio cerrado</strong> → todos los barberos aparecen en rojo ese día</li>\n              <li>• <strong>Barbero específico</strong> → solo ese barbero aparece no disponible</li>\n              <li>• <strong>Rango de fechas</strong> → ejemplo: vacaciones del 15 al 30 de junio</li>\n              <li>• <strong>Los cambios se reflejan inmediatamente</strong> en la tienda pública</li>\n            </ul>\n          </div>\n        </div>\n      )}\n\n      {/* ── MODAL NUEVO BLOQUEO ── */}\n      {showModal && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>{setShowModal(false);resetModal()}}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl shadow-2xl max-h-[90vh] overflow-y-auto\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"flex items-center justify-between px-5 py-4 border-b border-gray-100\">\n              <p className=\"font-bold text-gray-900 flex items-center gap-2\">\n                <Lock size={15} className=\"text-red-500\"/> Nuevo bloqueo\n              </p>\n              <button onClick={()=>{setShowModal(false);resetModal()}}\n                className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400 hover:bg-gray-100\">\n                <X size={15}/>\n              </button>\n            </div>\n            <div className=\"p-5 space-y-4\">\n\n              {/* Quién */}\n              <div>\n                <label className=\"field-label text-xs\">¿A quién afecta?</label>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {[\n                    { val:'business', label:'🏪 Todo el negocio' },\n                    { val:'staff',    label:'✂️ Un barbero' },\n                  ].map(({ val, label }) => (\n                    <button key={val} type=\"button\" onClick={() => setBlockTarget(val as 'business'|'staff')}\n                      className={cn('rounded-xl border-2 p-3 text-xs font-semibold transition-all',\n                        blockTarget===val?'border-red-500 bg-red-50 text-red-700':'border-gray-100 text-gray-600 hover:border-gray-300')}>\n                      {label}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              {/* Barbero específico */}\n              {blockTarget==='staff' && staff.length>0 && (\n                <div>\n                  <label className=\"field-label text-xs\">Barbero</label>\n                  <div className=\"flex flex-wrap gap-2\">\n                    {staff.map(s=>(\n                      <button key={s.id} type=\"button\" onClick={()=>setBlockStaffId(s.id)}\n                        className={cn('flex items-center gap-1.5 rounded-xl px-3 py-2 text-xs font-semibold transition-all',\n                          blockStaffId===s.id?'text-white':'bg-gray-100 text-gray-700')}\n                        style={blockStaffId===s.id?{background:s.color||color}:{}}>\n                        {s.name}\n                      </button>\n                    ))}\n                    <button type=\"button\" onClick={()=>setBlockStaffId('')}\n                      className={cn('rounded-xl px-3 py-2 text-xs font-semibold transition-all',\n                        blockStaffId===''?'bg-gray-800 text-white':'bg-gray-100 text-gray-700')}>\n                      Todos\n                    </button>\n                  </div>\n                </div>\n              )}\n\n              {/* Tipo de bloqueo */}\n              <div>\n                <label className=\"field-label text-xs\">Tipo de bloqueo</label>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {[\n                    { val:'day',   label:'📅 Un día' },\n                    { val:'range', label:'📆 Rango de días' },\n                    { val:'time',  label:'🕐 Horario' },\n                  ].map(({ val, label }) => (\n                    <button key={val} type=\"button\" onClick={() => setBlockType(val as 'day'|'range'|'time')}\n                      className={cn('rounded-xl border-2 p-2.5 text-xs font-semibold transition-all text-center',\n                        blockType===val?'border-gray-900 bg-gray-900 text-white':'border-gray-100 text-gray-600 hover:border-gray-300')}>\n                      {label}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              {/* Fecha(s) */}\n              {blockType==='day' && (\n                <div>\n                  <label className=\"field-label text-xs\">Fecha</label>\n                  <input type=\"date\" value={blockDate} onChange={e=>setBlockDate(e.target.value)}\n                    className=\"input-base\" min={today}/>\n                </div>\n              )}\n              {blockType==='range' && (\n                <div className=\"grid grid-cols-2 gap-3\">\n                  <div>\n                    <label className=\"field-label text-xs\">Desde</label>\n                    <input type=\"date\" value={blockFrom} onChange={e=>setBlockFrom(e.target.value)}\n                      className=\"input-base\" min={today}/>\n                  </div>\n                  <div>\n                    <label className=\"field-label text-xs\">Hasta</label>\n                    <input type=\"date\" value={blockTo} onChange={e=>setBlockTo(e.target.value)}\n                      className=\"input-base\" min={blockFrom||today}/>\n                  </div>\n                </div>\n              )}\n              {blockType==='time' && (\n                <>\n                  <div>\n                    <label className=\"field-label text-xs\">Fecha</label>\n                    <input type=\"date\" value={blockDate} onChange={e=>setBlockDate(e.target.value)}\n                      className=\"input-base\" min={today}/>\n                  </div>\n                  <div className=\"grid grid-cols-2 gap-3\">\n                    <div>\n                      <label className=\"field-label text-xs\">Hora desde</label>\n                      <input type=\"time\" value={blockTimeFrom} onChange={e=>setBlockTimeFrom(e.target.value)}\n                        className=\"input-base\"/>\n                    </div>\n                    <div>\n                      <label className=\"field-label text-xs\">Hora hasta</label>\n                      <input type=\"time\" value={blockTimeTo} onChange={e=>setBlockTimeTo(e.target.value)}\n                        className=\"input-base\"/>\n                    </div>\n                  </div>\n                </>\n              )}\n\n              {/* Motivo */}\n              <div>\n                <label className=\"field-label text-xs\">Motivo</label>\n                <div className=\"flex flex-wrap gap-2 mb-2\">\n                  {REASONS.map(r=>(\n                    <button key={r} type=\"button\" onClick={()=>setBlockReason(r)}\n                      className={cn('rounded-full px-3 py-1.5 text-xs font-medium transition-all',\n                        blockReason===r?'bg-gray-900 text-white':'bg-gray-100 text-gray-600 hover:bg-gray-200')}>\n                      {r}\n                    </button>\n                  ))}\n                </div>\n                <input type=\"text\" value={blockReason} onChange={e=>setBlockReason(e.target.value)}\n                  placeholder=\"Motivo personalizado\" className=\"input-base text-sm\"/>\n              </div>\n\n              {/* Warning */}\n              <div className=\"rounded-xl bg-amber-50 border border-amber-100 px-4 py-3 flex items-start gap-2\">\n                <AlertTriangle size={13} className=\"text-amber-500 shrink-0 mt-0.5\"/>\n                <p className=\"text-xs text-amber-700\">\n                  Los días bloqueados aparecerán en <strong>rojo</strong> en la tienda pública y no se podrán reservar. Los turnos existentes no se cancelan automáticamente.\n                </p>\n              </div>\n\n              <div className=\"flex gap-3 pb-2\">\n                <button onClick={addBlock}\n                  disabled={blockSaving || (blockType==='day'&&!blockDate) || (blockType==='range'&&(!blockFrom||!blockTo))}\n                  className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3\n                             text-sm font-bold text-white disabled:opacity-40 bg-red-600\">\n                  {blockSaving?<Loader2 size={14} className=\"animate-spin\"/>:<Lock size={14}/>}\n                  {blockSaving?'Guardando...':'Confirmar bloqueo'}\n                </button>\n                <button onClick={()=>{setShowModal(false);resetModal()}}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm font-medium text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/barbershop/BarbershopHub.tsx"] = "// app/admin/barbershop/BarbershopHub.tsx\n'use client'\nimport { useState, useMemo } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  Calendar, Users, Clock, MapPin, Plus, ChevronLeft, ChevronRight,\n  Check, X, Phone, MessageCircle, Edit2, Trash2, Loader2,\n  AlertCircle, Settings, MoreHorizontal, Building2,\n} from 'lucide-react'\nimport { cn, formatPrice } from '@/lib/utils'\nimport type { Booking, Staff, Branch, Product, BookingStatus } from '@/types'\n\ninterface Props {\n  businessId: string; businessName: string; currency: string\n  whatsapp: string; primaryColor: string\n  bookings: Booking[]; staff: Staff[]; branches: Branch[]; services: Product[]\n}\n\ntype Tab = 'agenda' | 'staff' | 'branches' | 'availability'\n\nconst DAYS_ES = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst DAYS_FULL = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']\nconst MONTHS_ES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',\n  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']\n\nconst STATUS_CFG: Record<BookingStatus, { label:string; bg:string; text:string; dot:string }> = {\n  pending:   { label:'Pendiente',   bg:'bg-amber-50',  text:'text-amber-700',  dot:'bg-amber-400'  },\n  confirmed: { label:'Confirmado',  bg:'bg-blue-50',   text:'text-blue-700',   dot:'bg-blue-500'   },\n  done:      { label:'Realizado',   bg:'bg-green-50',  text:'text-green-700',  dot:'bg-green-500'  },\n  cancelled: { label:'Cancelado',   bg:'bg-red-50',    text:'text-red-600',    dot:'bg-red-400'    },\n  noshow:    { label:'No asistió',  bg:'bg-gray-100',  text:'text-gray-500',   dot:'bg-gray-400'   },\n}\n\nfunction StatusBadge({ status }: { status: BookingStatus }) {\n  const cfg = STATUS_CFG[status]\n  return (\n    <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium ${cfg.bg} ${cfg.text}`}>\n      <span className={`h-1.5 w-1.5 rounded-full ${cfg.dot}`}/>\n      {cfg.label}\n    </span>\n  )\n}\n\n// Generar slots de tiempo cada N minutos\nfunction generateSlots(start: string, end: string, step = 30): string[] {\n  const slots: string[] = []\n  const [sh,sm] = start.split(':').map(Number)\n  const [eh,em] = end.split(':').map(Number)\n  let cur = sh*60+sm\n  const endMin = eh*60+em\n  while (cur < endMin) {\n    const h = Math.floor(cur/60).toString().padStart(2,'0')\n    const m = (cur%60).toString().padStart(2,'0')\n    slots.push(`${h}:${m}`)\n    cur += step\n  }\n  return slots\n}\n\nexport default function BarbershopHub({\n  businessId, businessName, currency, whatsapp, primaryColor,\n  bookings: initialBookings, staff, branches, services,\n}: Props) {\n  const supabase = createClient()\n  const [tab,          setTab]          = useState<Tab>('agenda')\n  const [bookings,     setBookings]     = useState<Booking[]>(initialBookings)\n  const [selectedDate, setSelectedDate] = useState(new Date())\n  const [filterStaff,  setFilterStaff]  = useState<string|null>(null)\n  const [filterBranch, setFilterBranch] = useState<string|null>(null)\n  const [showNewBooking, setShowNewBooking] = useState(false)\n  const [editingBooking,  setEditingBooking]  = useState<Booking|null>(null)\n\n  const dateStr = selectedDate.toISOString().split('T')[0]\n\n  // Turnos del día seleccionado\n  const todayBookings = useMemo(() => {\n    let list = bookings.filter(b => b.date === dateStr)\n    if (filterStaff)  list = list.filter(b => b.staff_id === filterStaff)\n    if (filterBranch) list = list.filter(b => b.branch_id === filterBranch)\n    return list.sort((a,b) => a.start_time.localeCompare(b.start_time))\n  }, [bookings, dateStr, filterStaff, filterBranch])\n\n  // Stats del día\n  const confirmed = todayBookings.filter(b=>b.status==='confirmed'||b.status==='done').length\n  const pending   = todayBookings.filter(b=>b.status==='pending').length\n  const revenue   = todayBookings.filter(b=>b.status==='done').reduce((a,b)=>a+(b.price??0),0)\n\n  // Navegar fecha\n  function prevDay() { const d=new Date(selectedDate); d.setDate(d.getDate()-1); setSelectedDate(d) }\n  function nextDay() { const d=new Date(selectedDate); d.setDate(d.getDate()+1); setSelectedDate(d) }\n  function goToday() { setSelectedDate(new Date()) }\n\n  const isToday = dateStr === new Date().toISOString().split('T')[0]\n\n  async function updateStatus(id: string, status: BookingStatus) {\n    await supabase.from('bookings').update({ status }).eq('id', id)\n    setBookings(prev => prev.map(b => b.id===id ? {...b,status} : b))\n  }\n\n  async function deleteBooking(id: string) {\n    if (!confirm('¿Eliminar este turno?')) return\n    await supabase.from('bookings').delete().eq('id', id)\n    setBookings(prev => prev.filter(b => b.id !== id))\n  }\n\n  return (\n    <div className=\"space-y-4 animate-fade-in pb-4\">\n\n      {/* Header */}\n      <div className=\"flex items-start justify-between gap-3\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">Agenda</h1>\n          <p className=\"text-xs text-gray-400 mt-0.5\">{businessName}</p>\n        </div>\n        <button onClick={() => setShowNewBooking(true)}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold\n                     text-white active:scale-[0.98] transition-all\"\n          style={{ background: primaryColor }}>\n          <Plus size={15} />\n          <span className=\"hidden sm:inline\">Nuevo turno</span>\n          <span className=\"sm:hidden\">Nuevo</span>\n        </button>\n      </div>\n\n      {/* Tabs */}\n      <div className=\"flex items-center gap-1 bg-gray-100 rounded-xl p-1 w-fit\">\n        {([\n          { key:'agenda',   label:'Agenda',     icon: Calendar   },\n          { key:'staff',    label:'Barberos',   icon: Users      },\n          { key:'branches',     label:'Sucursales',    icon: Building2  },\n          { key:'availability', label:'Disponibilidad', icon: Clock      },\n        ] as { key:Tab; label:string; icon:React.ElementType }[]).map(({ key, label, icon: Icon }) => (\n          <button key={key} onClick={() => setTab(key)}\n            className={cn('flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium transition-all',\n              tab===key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700')}>\n            <Icon size={13} />{label}\n          </button>\n        ))}\n      </div>\n\n      {/* ── TAB AGENDA ── */}\n      {tab === 'agenda' && (\n        <div className=\"space-y-4\">\n          {/* Navegación fecha */}\n          <div className=\"flex items-center gap-3\">\n            <button onClick={prevDay}\n              className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                         bg-white text-gray-500 hover:bg-gray-50 transition-all\">\n              <ChevronLeft size={16}/>\n            </button>\n\n            <div className=\"flex-1 text-center\">\n              <p className=\"text-sm font-bold text-gray-900\">\n                {DAYS_FULL[selectedDate.getDay()]}{' '}\n                {selectedDate.getDate()} de{' '}\n                {MONTHS_ES[selectedDate.getMonth()]}\n              </p>\n              {!isToday && (\n                <button onClick={goToday} className=\"text-xs mt-0.5 hover:underline\"\n                  style={{ color: primaryColor }}>\n                  Ir a hoy\n                </button>\n              )}\n            </div>\n\n            <button onClick={nextDay}\n              className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                         bg-white text-gray-500 hover:bg-gray-50 transition-all\">\n              <ChevronRight size={16}/>\n            </button>\n          </div>\n\n          {/* Filtros */}\n          {(staff.length > 1 || branches.length > 1) && (\n            <div className=\"flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide\">\n              <select value={filterStaff??''} onChange={e=>setFilterStaff(e.target.value||null)}\n                className=\"rounded-xl border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-700 shrink-0\">\n                <option value=\"\">Todos los barberos</option>\n                {staff.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}\n              </select>\n              {branches.length > 1 && (\n                <select value={filterBranch??''} onChange={e=>setFilterBranch(e.target.value||null)}\n                  className=\"rounded-xl border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-700 shrink-0\">\n                  <option value=\"\">Todas las sucursales</option>\n                  {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                </select>\n              )}\n            </div>\n          )}\n\n          {/* Stats del día */}\n          <div className=\"grid grid-cols-3 gap-3\">\n            {[\n              { label:'Turnos', value:todayBookings.length, color:'text-gray-900' },\n              { label:'Confirmados', value:confirmed, color:'text-blue-600' },\n              { label:'Pendientes', value:pending, color: pending>0?'text-amber-600':'text-gray-400' },\n            ].map(({label,value,color})=>(\n              <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-3 text-center shadow-sm\">\n                <p className={`text-xl font-bold ${color}`}>{value}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5\">{label}</p>\n              </div>\n            ))}\n          </div>\n\n          {/* Lista de turnos */}\n          {todayBookings.length === 0 ? (\n            <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-14 text-center\">\n              <Calendar size={28} className=\"mx-auto text-gray-200 mb-3\"/>\n              <p className=\"text-sm font-medium text-gray-400\">Sin turnos para este día</p>\n              <button onClick={() => setShowNewBooking(true)}\n                className=\"mt-3 text-xs font-semibold hover:underline\"\n                style={{ color: primaryColor }}>\n                + Agregar turno\n              </button>\n            </div>\n          ) : (\n            <div className=\"space-y-2\">\n              {todayBookings.map(booking => (\n                <BookingCard\n                  key={booking.id}\n                  booking={booking}\n                  currency={currency}\n                  whatsapp={whatsapp}\n                  onStatusChange={updateStatus}\n                  onEdit={() => setEditingBooking(booking)}\n                  onDelete={() => deleteBooking(booking.id)}\n                  primaryColor={primaryColor}\n                />\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n\n      {/* ── TAB STAFF ── */}\n      {tab === 'staff' && (\n        <StaffTab\n          businessId={businessId}\n          staff={staff}\n          branches={branches}\n          primaryColor={primaryColor}\n        />\n      )}\n\n      {/* ── TAB BRANCHES ── */}\n      {tab === 'branches' && (\n        <BranchesTab\n          businessId={businessId}\n          branches={branches}\n          primaryColor={primaryColor}\n        />\n      )}\n\n      {/* Modal nuevo/editar turno */}\n      {(showNewBooking || editingBooking) && (\n        <BookingModal\n          businessId={businessId}\n          staff={staff}\n          branches={branches}\n          services={services}\n          booking={editingBooking}\n          selectedDate={dateStr}\n          existingBookings={bookings}\n          onClose={() => { setShowNewBooking(false); setEditingBooking(null) }}\n          onSave={(saved) => {\n            setBookings(prev =>\n              editingBooking\n                ? prev.map(b => b.id===saved.id ? saved : b)\n                : [...prev, saved]\n            )\n            setShowNewBooking(false)\n            setEditingBooking(null)\n          }}\n          primaryColor={primaryColor}\n        />\n      )}\n    </div>\n  )\n}\n\n// ── Booking Card ──────────────────────────────────────────────\nfunction BookingCard({ booking, currency, whatsapp, onStatusChange, onEdit, onDelete, primaryColor }: {\n  booking: Booking; currency: string; whatsapp: string\n  onStatusChange: (id:string,s:BookingStatus)=>void\n  onEdit: ()=>void; onDelete: ()=>void; primaryColor: string\n}) {\n  const [menuOpen, setMenuOpen] = useState(false)\n  const waLink = booking.customer_phone\n    ? `https://wa.me/${booking.customer_phone.replace(/\\D/g,'')}?text=${encodeURIComponent(\n        `Hola ${booking.customer_name}! Te confirmamos tu turno para el ${booking.date} a las ${booking.start_time}.`\n      )}`\n    : null\n\n  return (\n    <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm\">\n      <div className=\"flex items-start gap-3 p-4\">\n        {/* Hora + color staff */}\n        <div className=\"shrink-0 text-center min-w-[48px]\">\n          <div className=\"h-10 w-10 rounded-xl flex items-center justify-center text-white text-xs font-bold\"\n            style={{ background: booking.staff?.color ?? primaryColor }}>\n            {booking.start_time.slice(0,5)}\n          </div>\n          <p className=\"text-[10px] text-gray-400 mt-1\">{booking.end_time.slice(0,5)}</p>\n        </div>\n\n        {/* Info */}\n        <div className=\"flex-1 min-w-0\">\n          <div className=\"flex items-start justify-between gap-2\">\n            <div>\n              <p className=\"text-sm font-bold text-gray-900\">{booking.customer_name}</p>\n              {booking.product && (\n                <p className=\"text-xs text-gray-500 mt-0.5\">{booking.product.name}</p>\n              )}\n              {booking.staff && (\n                <p className=\"text-xs text-gray-400\">✂️ {booking.staff.name}</p>\n              )}\n              {booking.branch && (\n                <p className=\"text-xs text-gray-400\">📍 {booking.branch.name}</p>\n              )}\n            </div>\n            <StatusBadge status={booking.status}/>\n          </div>\n\n          {/* Precio */}\n          {booking.price != null && (\n            <p className=\"text-sm font-bold mt-1.5\" style={{ color: primaryColor }}>\n              {formatPrice(booking.price, currency)}\n            </p>\n          )}\n\n          {/* Acciones */}\n          <div className=\"flex items-center gap-2 mt-3 flex-wrap\">\n            {booking.status === 'pending' && (\n              <button onClick={() => onStatusChange(booking.id,'confirmed')}\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold text-white\"\n                style={{ background: primaryColor }}>\n                <Check size={11}/> Confirmar\n              </button>\n            )}\n            {(booking.status==='confirmed'||booking.status==='pending') && (\n              <button onClick={() => onStatusChange(booking.id,'done')}\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold\n                           bg-green-500 text-white\">\n                <Check size={11}/> Realizado\n              </button>\n            )}\n            {waLink && (\n              <a href={waLink} target=\"_blank\"\n                className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold\n                           bg-green-500 text-white\">\n                <MessageCircle size={11}/> WA\n              </a>\n            )}\n            <div className=\"relative ml-auto\">\n              <button onClick={() => setMenuOpen(o=>!o)}\n                className=\"flex h-7 w-7 items-center justify-center rounded-lg text-gray-400\n                           hover:bg-gray-100 transition-colors\">\n                <MoreHorizontal size={14}/>\n              </button>\n              {menuOpen && (\n                <>\n                  <div className=\"fixed inset-0 z-10\" onClick={() => setMenuOpen(false)}/>\n                  <div className=\"absolute right-0 top-8 z-20 w-36 rounded-xl border border-gray-200\n                                  bg-white py-1 shadow-lg\">\n                    <button onClick={()=>{onEdit();setMenuOpen(false)}}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-gray-700 hover:bg-gray-50\">\n                      <Edit2 size={12}/> Editar\n                    </button>\n                    <button onClick={()=>onStatusChange(booking.id,'cancelled')}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-red-600 hover:bg-red-50\">\n                      <X size={12}/> Cancelar\n                    </button>\n                    <button onClick={()=>{onDelete();setMenuOpen(false)}}\n                      className=\"w-full flex items-center gap-2 px-3 py-2 text-xs text-red-600 hover:bg-red-50\">\n                      <Trash2 size={12}/> Eliminar\n                    </button>\n                  </div>\n                </>\n              )}\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  )\n}\n\n// ── Modal Booking ─────────────────────────────────────────────\nfunction BookingModal({ businessId, staff, branches, services, booking, selectedDate,\n  existingBookings, onClose, onSave, primaryColor }: {\n  businessId:string; staff:Staff[]; branches:Branch[]; services:Product[]\n  booking:Booking|null; selectedDate:string; existingBookings:Booking[]\n  onClose:()=>void; onSave:(b:Booking)=>void; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [loading,  setLoading]  = useState(false)\n  const [error,    setError]    = useState<string|null>(null)\n\n  const [customerName,  setCustomerName]  = useState(booking?.customer_name ?? '')\n  const [customerPhone, setCustomerPhone] = useState(booking?.customer_phone ?? '')\n  const [staffId,       setStaffId]       = useState(booking?.staff_id ?? (staff[0]?.id ?? ''))\n  const [branchId,      setBranchId]      = useState(booking?.branch_id ?? (branches[0]?.id ?? ''))\n  const [serviceId,     setServiceId]     = useState(booking?.product_id ?? '')\n  const [date,          setDate]          = useState(booking?.date ?? selectedDate)\n  const [startTime,     setStartTime]     = useState(booking?.start_time ?? '09:00')\n  const [duration,      setDuration]      = useState(booking?.duration_min ?? 30)\n  const [price,         setPrice]         = useState(booking?.price?.toString() ?? '')\n  const [notes,         setNotes]         = useState(booking?.notes ?? '')\n  const [status,        setStatus]        = useState<BookingStatus>(booking?.status ?? 'confirmed')\n\n  // Calcular end_time\n  const [sh, sm] = startTime.split(':').map(Number)\n  const endMin = sh*60 + sm + duration\n  const endTime = `${Math.floor(endMin/60).toString().padStart(2,'0')}:${(endMin%60).toString().padStart(2,'0')}`\n\n  // Verificar conflictos\n  const hasConflict = existingBookings.some(b => {\n    if (b.id === booking?.id) return false\n    if (b.staff_id !== staffId || b.date !== date) return false\n    if (b.status === 'cancelled' || b.status === 'noshow') return false\n    const bStart = b.start_time.slice(0,5)\n    const bEnd   = b.end_time.slice(0,5)\n    return startTime < bEnd && endTime > bStart\n  })\n\n  // Auto-completar precio desde servicio\n  function handleServiceChange(id: string) {\n    setServiceId(id)\n    const svc = services.find(s=>s.id===id)\n    if (svc?.price) setPrice(svc.price.toString())\n  }\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (hasConflict) { setError('Hay un conflicto de horario con otro turno'); return }\n    setLoading(true); setError(null)\n    try {\n      const payload = {\n        business_id:    businessId,\n        staff_id:       staffId || null,\n        branch_id:      branchId || null,\n        product_id:     serviceId || null,\n        customer_name:  customerName.trim(),\n        customer_phone: customerPhone.trim() || null,\n        date,\n        start_time:     startTime,\n        end_time:       endTime,\n        duration_min:   duration,\n        price:          price ? parseFloat(price) : null,\n        notes:          notes.trim() || null,\n        status,\n        source:         'admin',\n      }\n      if (booking) {\n        const { data,error:e } = await supabase.from('bookings')\n          .update(payload).eq('id',booking.id)\n          .select('*, staff:staff(name,color), branch:branches(name), product:products(name,price)')\n          .single()\n        if (e) throw e; onSave(data as Booking)\n      } else {\n        const { data,error:e } = await supabase.from('bookings')\n          .insert(payload)\n          .select('*, staff:staff(name,color), branch:branches(name), product:products(name,price)')\n          .single()\n        if (e) throw e; onSave(data as Booking)\n      }\n    } catch(e:unknown) {\n      setError(e instanceof Error?e.message:'Error al guardar')\n    } finally { setLoading(false) }\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n      <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={onClose}/>\n      <div className=\"relative bg-white w-full sm:max-w-lg rounded-t-3xl sm:rounded-2xl\n                      shadow-2xl max-h-[92vh] overflow-y-auto animate-slide-up\">\n        {/* Handle mobile */}\n        <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n          <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n        </div>\n\n        <div className=\"flex items-center justify-between px-5 py-4 border-b border-gray-100 sticky top-0 bg-white z-10\">\n          <p className=\"font-bold text-gray-900\">{booking ? 'Editar turno' : 'Nuevo turno'}</p>\n          <button onClick={onClose}\n            className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400\n                       hover:bg-gray-100 transition-colors\">\n            <X size={16}/>\n          </button>\n        </div>\n\n        <form onSubmit={handleSave} className=\"p-5 space-y-4\">\n          {/* Cliente */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div className=\"col-span-2\">\n              <label className=\"field-label\">Nombre del cliente <span className=\"text-red-400\">*</span></label>\n              <input type=\"text\" required value={customerName} onChange={e=>setCustomerName(e.target.value)}\n                placeholder=\"Nombre completo\" className=\"input-base\"/>\n            </div>\n            <div className=\"col-span-2\">\n              <label className=\"field-label\">Teléfono / WhatsApp</label>\n              <input type=\"tel\" value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)}\n                placeholder=\"099123456\" className=\"input-base\" inputMode=\"numeric\"/>\n            </div>\n          </div>\n\n          {/* Servicio */}\n          {services.length > 0 && (\n            <div>\n              <label className=\"field-label\">Servicio</label>\n              <select value={serviceId} onChange={e=>handleServiceChange(e.target.value)} className=\"input-base\">\n                <option value=\"\">Sin especificar</option>\n                {services.map(s=><option key={s.id} value={s.id}>{s.name} — ${s.price}</option>)}\n              </select>\n            </div>\n          )}\n\n          {/* Barbero + Sucursal */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            {staff.length > 0 && (\n              <div>\n                <label className=\"field-label\">Barbero</label>\n                <select value={staffId} onChange={e=>setStaffId(e.target.value)} className=\"input-base\">\n                  <option value=\"\">Sin asignar</option>\n                  {staff.map(s=>(\n                    <option key={s.id} value={s.id}>{s.name}</option>\n                  ))}\n                </select>\n              </div>\n            )}\n            {branches.length > 1 && (\n              <div>\n                <label className=\"field-label\">Sucursal</label>\n                <select value={branchId} onChange={e=>setBranchId(e.target.value)} className=\"input-base\">\n                  {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                </select>\n              </div>\n            )}\n          </div>\n\n          {/* Fecha + Hora */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Fecha</label>\n              <input type=\"date\" value={date} onChange={e=>setDate(e.target.value)} className=\"input-base\"/>\n            </div>\n            <div>\n              <label className=\"field-label\">Hora inicio</label>\n              <input type=\"time\" value={startTime} onChange={e=>setStartTime(e.target.value)} className=\"input-base\"/>\n            </div>\n          </div>\n\n          {/* Duración */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Duración (min)</label>\n              <select value={duration} onChange={e=>setDuration(parseInt(e.target.value))} className=\"input-base\">\n                {[15,20,30,45,60,90,120].map(d=>(\n                  <option key={d} value={d}>{d} min</option>\n                ))}\n              </select>\n            </div>\n            <div>\n              <label className=\"field-label\">Fin estimado</label>\n              <input type=\"text\" value={endTime} readOnly\n                className=\"input-base bg-gray-50 text-gray-500 cursor-not-allowed\"/>\n            </div>\n          </div>\n\n          {/* Conflicto */}\n          {hasConflict && (\n            <div className=\"flex items-center gap-2 rounded-xl bg-red-50 border border-red-100 px-4 py-3\">\n              <AlertCircle size={14} className=\"text-red-500 shrink-0\"/>\n              <p className=\"text-xs text-red-700 font-medium\">\n                ⚠️ Este barbero ya tiene un turno en ese horario\n              </p>\n            </div>\n          )}\n\n          {/* Precio + Estado */}\n          <div className=\"grid grid-cols-2 gap-3\">\n            <div>\n              <label className=\"field-label\">Precio</label>\n              <input type=\"number\" min=\"0\" step=\"0.01\" value={price}\n                onChange={e=>setPrice(e.target.value)} placeholder=\"0\" className=\"input-base\"/>\n            </div>\n            <div>\n              <label className=\"field-label\">Estado</label>\n              <select value={status} onChange={e=>setStatus(e.target.value as BookingStatus)} className=\"input-base\">\n                <option value=\"pending\">Pendiente</option>\n                <option value=\"confirmed\">Confirmado</option>\n                <option value=\"done\">Realizado</option>\n                <option value=\"cancelled\">Cancelado</option>\n                <option value=\"noshow\">No asistió</option>\n              </select>\n            </div>\n          </div>\n\n          <div>\n            <label className=\"field-label\">Notas</label>\n            <textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={2}\n              placeholder=\"Observaciones del turno...\" className=\"input-base resize-none\"/>\n          </div>\n\n          {error && (\n            <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n          )}\n\n          <div className=\"flex gap-3 pt-2 pb-2\">\n            <button type=\"submit\" disabled={loading||hasConflict}\n              className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3\n                         text-sm font-semibold text-white disabled:opacity-40\"\n              style={{ background: primaryColor }}>\n              {loading&&<Loader2 size={14} className=\"animate-spin\"/>}\n              {loading?'Guardando...':booking?'Guardar cambios':'Crear turno'}\n            </button>\n            <button type=\"button\" onClick={onClose}\n              className=\"rounded-xl border border-gray-200 px-5 py-3 text-sm font-medium text-gray-600\">\n              Cancelar\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  )\n}\n\n// ── Staff Tab ─────────────────────────────────────────────────\nfunction StaffTab({ businessId, staff, branches, primaryColor }: {\n  businessId:string; staff:Staff[]; branches:Branch[]; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [list, setList] = useState<Staff[]>(staff)\n  const [showForm, setShowForm] = useState(false)\n  const [editing, setEditing] = useState<Staff|null>(null)\n\n  const COLORS = ['#1565FF','#0B3EAB','#EC4899','#7C3AED','#059669','#D97706','#DC2626','#374151']\n\n  const [name,     setName]     = useState('')\n  const [role,     setRole]     = useState('barber')\n  const [bio,      setBio]      = useState('')\n  const [color,    setColor]    = useState('#1565FF')\n  const [branchId, setBranchId] = useState(branches[0]?.id ?? '')\n  const [loading,  setLoading]  = useState(false)\n\n  function openEdit(s: Staff) {\n    setEditing(s); setName(s.name); setRole(s.role)\n    setBio(s.bio??''); setColor(s.color); setBranchId(s.branch_id??'')\n    setShowForm(true)\n  }\n\n  function resetForm() {\n    setEditing(null); setName(''); setRole('barber')\n    setBio(''); setColor('#1565FF'); setBranchId(branches[0]?.id??'')\n  }\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim()) return\n    setLoading(true)\n    const payload = {\n      business_id: businessId, name:name.trim(), role, bio:bio.trim()||null,\n      color, branch_id:branchId||null, active:true,\n    }\n    if (editing) {\n      const { data } = await supabase.from('staff').update(payload).eq('id',editing.id).select('*').single()\n      if (data) setList(prev=>prev.map(s=>s.id===editing.id?data as Staff:s))\n    } else {\n      const { data } = await supabase.from('staff').insert(payload).select('*').single()\n      if (data) setList(prev=>[...prev,data as Staff])\n    }\n    setLoading(false); setShowForm(false); resetForm()\n  }\n\n  async function toggleActive(id: string, active: boolean) {\n    await supabase.from('staff').update({ active: !active }).eq('id', id)\n    setList(prev=>prev.map(s=>s.id===id?{...s,active:!active}:s))\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-sm text-gray-500\">{list.length} barberos registrados</p>\n        <button onClick={() => { resetForm(); setShowForm(true) }}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold text-white\"\n          style={{ background: primaryColor }}>\n          <Plus size={14}/> Agregar\n        </button>\n      </div>\n\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-12 text-center\">\n          <Users size={24} className=\"mx-auto text-gray-200 mb-2\"/>\n          <p className=\"text-sm text-gray-400\">Sin barberos registrados</p>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {list.map(s => (\n            <div key={s.id} className=\"flex items-center gap-3 bg-white rounded-2xl border border-gray-100 p-4\">\n              <div className=\"h-10 w-10 rounded-xl flex items-center justify-center text-white\n                              text-sm font-bold shrink-0\"\n                style={{ background: s.color }}>\n                {s.name.slice(0,1).toUpperCase()}\n              </div>\n              <div className=\"flex-1 min-w-0\">\n                <p className=\"text-sm font-bold text-gray-900\">{s.name}</p>\n                <p className=\"text-xs text-gray-400 capitalize\">{s.role} {s.branch?.name ? `· ${s.branch.name}` : ''}</p>\n                {s.bio && <p className=\"text-xs text-gray-400 truncate mt-0.5\">{s.bio}</p>}\n              </div>\n              <div className=\"flex items-center gap-1 shrink-0\">\n                <button onClick={() => openEdit(s)}\n                  className=\"h-8 w-8 flex items-center justify-center rounded-lg text-gray-400\n                             hover:bg-gray-100 transition-colors\">\n                  <Edit2 size={13}/>\n                </button>\n                <button onClick={() => toggleActive(s.id, s.active)}\n                  className={cn('h-8 w-8 flex items-center justify-center rounded-lg transition-colors',\n                    s.active ? 'text-green-500 hover:bg-green-50' : 'text-gray-300 hover:bg-gray-100')}>\n                  <Check size={13}/>\n                </button>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Form modal */}\n      {showForm && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>{setShowForm(false);resetForm()}}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl\n                          shadow-2xl max-h-[85vh] overflow-y-auto\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"px-5 py-4 border-b border-gray-100\">\n              <p className=\"font-bold text-gray-900\">{editing?'Editar barbero':'Nuevo barbero'}</p>\n            </div>\n            <form onSubmit={handleSave} className=\"p-5 space-y-4\">\n              <div>\n                <label className=\"field-label\">Nombre <span className=\"text-red-400\">*</span></label>\n                <input type=\"text\" required value={name} onChange={e=>setName(e.target.value)}\n                  placeholder=\"Nombre del barbero\" className=\"input-base\"/>\n              </div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div>\n                  <label className=\"field-label\">Rol</label>\n                  <select value={role} onChange={e=>setRole(e.target.value)} className=\"input-base\">\n                    <option value=\"barber\">Barbero</option>\n                    <option value=\"stylist\">Estilista</option>\n                    <option value=\"specialist\">Especialista</option>\n                  </select>\n                </div>\n                {branches.length > 1 && (\n                  <div>\n                    <label className=\"field-label\">Sucursal</label>\n                    <select value={branchId} onChange={e=>setBranchId(e.target.value)} className=\"input-base\">\n                      {branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}\n                    </select>\n                  </div>\n                )}\n              </div>\n              <div>\n                <label className=\"field-label\">Color en agenda</label>\n                <div className=\"flex items-center gap-2 flex-wrap\">\n                  {COLORS.map(c=>(\n                    <button key={c} type=\"button\" onClick={()=>setColor(c)}\n                      className={cn('h-8 w-8 rounded-xl transition-all',\n                        color===c?'ring-2 ring-offset-2 ring-gray-400 scale-110':'')}\n                      style={{background:c}}/>\n                  ))}\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Bio</label>\n                <textarea value={bio} onChange={e=>setBio(e.target.value)} rows={2}\n                  placeholder=\"Especialidad, años de experiencia...\" className=\"input-base resize-none\"/>\n              </div>\n              <div className=\"flex gap-3 pt-1 pb-2\">\n                <button type=\"submit\" disabled={loading}\n                  className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3\n                             text-sm font-semibold text-white disabled:opacity-40\"\n                  style={{background:primaryColor}}>\n                  {loading&&<Loader2 size={13} className=\"animate-spin\"/>}\n                  {loading?'Guardando...':editing?'Guardar':'Agregar barbero'}\n                </button>\n                <button type=\"button\" onClick={()=>{setShowForm(false);resetForm()}}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Branches Tab ──────────────────────────────────────────────\nfunction BranchesTab({ businessId, branches, primaryColor }: {\n  businessId:string; branches:Branch[]; primaryColor:string\n}) {\n  const supabase = createClient()\n  const [list,     setList]     = useState<Branch[]>(branches)\n  const [showForm, setShowForm] = useState(false)\n  const [loading,  setLoading]  = useState(false)\n  const [name,     setName]     = useState('')\n  const [address,  setAddress]  = useState('')\n  const [phone,    setPhone]    = useState('')\n  const [whatsapp, setWhatsapp] = useState('')\n  const [city,     setCity]     = useState('')\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim()) return\n    setLoading(true)\n    const { data } = await supabase.from('branches').insert({\n      business_id:businessId, name:name.trim(),\n      address:address.trim()||null, phone:phone.trim()||null,\n      whatsapp:whatsapp.replace(/\\D/g,'')||null, city:city.trim()||null,\n      is_main:false, active:true,\n    }).select('*').single()\n    if (data) setList(prev=>[...prev,data as Branch])\n    setLoading(false); setShowForm(false)\n    setName('');setAddress('');setPhone('');setWhatsapp('');setCity('')\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"text-sm text-gray-500\">{list.length} sucursales</p>\n        <button onClick={()=>setShowForm(true)}\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold text-white\"\n          style={{background:primaryColor}}>\n          <Plus size={14}/> Nueva sucursal\n        </button>\n      </div>\n\n      <div className=\"space-y-2\">\n        {list.map(b=>(\n          <div key={b.id} className=\"bg-white rounded-2xl border border-gray-100 p-4\">\n            <div className=\"flex items-center gap-2 mb-2\">\n              <div className=\"h-8 w-8 rounded-xl flex items-center justify-center text-white text-xs\"\n                style={{background:primaryColor}}>\n                <Building2 size={14}/>\n              </div>\n              <div>\n                <p className=\"text-sm font-bold text-gray-900\">{b.name}</p>\n                {b.is_main && <span className=\"text-[10px] text-blue-600 font-medium\">Principal</span>}\n              </div>\n            </div>\n            {b.address&&<p className=\"text-xs text-gray-500 flex items-center gap-1\"><MapPin size={11}/>{b.address}{b.city?`, ${b.city}`:''}</p>}\n            {b.phone&&<p className=\"text-xs text-gray-500 flex items-center gap-1 mt-1\"><Phone size={11}/>{b.phone}</p>}\n            {b.whatsapp&&(\n              <a href={`https://wa.me/${b.whatsapp}`} target=\"_blank\"\n                className=\"inline-flex items-center gap-1 text-xs text-green-600 mt-1\">\n                <MessageCircle size={11}/>{b.whatsapp}\n              </a>\n            )}\n          </div>\n        ))}\n      </div>\n\n      {showForm && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>setShowForm(false)}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl shadow-2xl\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"px-5 py-4 border-b border-gray-100\">\n              <p className=\"font-bold text-gray-900\">Nueva sucursal</p>\n            </div>\n            <form onSubmit={handleSave} className=\"p-5 space-y-3\">\n              <div>\n                <label className=\"field-label\">Nombre <span className=\"text-red-400\">*</span></label>\n                <input type=\"text\" required value={name} onChange={e=>setName(e.target.value)}\n                  placeholder=\"Ej: Sucursal Centro\" className=\"input-base\"/>\n              </div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div>\n                  <label className=\"field-label\">Ciudad</label>\n                  <input type=\"text\" value={city} onChange={e=>setCity(e.target.value)}\n                    placeholder=\"Montevideo\" className=\"input-base\"/>\n                </div>\n                <div>\n                  <label className=\"field-label\">Teléfono</label>\n                  <input type=\"text\" value={phone} onChange={e=>setPhone(e.target.value)}\n                    placeholder=\"2900 0000\" className=\"input-base\"/>\n                </div>\n              </div>\n              <div>\n                <label className=\"field-label\">Dirección</label>\n                <input type=\"text\" value={address} onChange={e=>setAddress(e.target.value)}\n                  placeholder=\"Av. 18 de Julio 1234\" className=\"input-base\"/>\n              </div>\n              <div>\n                <label className=\"field-label\">WhatsApp</label>\n                <input type=\"text\" value={whatsapp} onChange={e=>setWhatsapp(e.target.value)}\n                  placeholder=\"59899000000\" className=\"input-base\" inputMode=\"numeric\"/>\n              </div>\n              <div className=\"flex gap-3 pt-2 pb-2\">\n                <button type=\"submit\" disabled={loading}\n                  className=\"flex-1 rounded-xl py-3 text-sm font-semibold text-white disabled:opacity-40\"\n                  style={{background:primaryColor}}>\n                  {loading?'Guardando...':'Crear sucursal'}\n                </button>\n                <button type=\"button\" onClick={()=>setShowForm(false)}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/api/bookings/availability/route.ts"] = "// app/api/bookings/availability/route.ts\n// Devuelve disponibilidad real considerando:\n// 1. Turnos ya reservados\n// 2. Slots bloqueados manualmente\n// 3. Días cerrados del negocio\n// 4. Horario de trabajo del barbero (staff_schedules)\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nexport async function GET(req: Request) {\n  try {\n    const { searchParams } = new URL(req.url)\n    const staffId    = searchParams.get('staffId')\n    const businessId = searchParams.get('businessId')\n    const from       = searchParams.get('from')\n    const to         = searchParams.get('to')\n\n    if (!from || !to || !businessId)\n      return NextResponse.json({ booked: {}, blocked: {}, closedDays: [], schedules: [] })\n\n    const supabase = createServiceClient()\n\n    const [bookingsRes, blockedRes, closedRes, schedulesRes] = await Promise.all([\n      // 1. Turnos reservados\n      (() => {\n        let q = supabase.from('bookings')\n          .select('date, start_time, end_time, status')\n          .eq('business_id', businessId)\n          .gte('date', from).lte('date', to)\n          .not('status', 'in', '(cancelled,noshow)')\n        if (staffId) q = q.eq('staff_id', staffId)\n        return q\n      })(),\n\n      // 2. Slots bloqueados manualmente\n      (() => {\n        let q = supabase.from('blocked_slots')\n          .select('date, date_from, date_to, time_slot, time_from, time_to, reason, staff_id')\n          .eq('business_id', businessId)\n        if (staffId) q = q.or(`staff_id.eq.${staffId},staff_id.is.null`)\n        return q\n      })(),\n\n      // 3. Días cerrados del negocio\n      supabase.from('business_closed_days')\n        .select('date, date_from, date_to, reason')\n        .eq('business_id', businessId),\n\n      // 4. Horarios del barbero\n      staffId\n        ? supabase.from('staff_schedules').select('*').eq('staff_id', staffId)\n        : Promise.resolve({ data: [] }),\n    ])\n\n    // ── Procesar turnos reservados ──\n    const bookedMap: Record<string, string[]> = {}\n    for (const b of bookingsRes.data ?? []) {\n      if (!bookedMap[b.date]) bookedMap[b.date] = []\n      bookedMap[b.date].push(b.start_time.slice(0, 5))\n    }\n\n    // ── Expandir rangos bloqueados en días individuales ──\n    const blockedMap: Record<string, {\n      allDay: boolean; slots: string[]; timeRanges: {from:string;to:string}[]; reason?: string\n    }> = {}\n\n    function addBlocked(date: string, data: {\n      allDay?: boolean; slot?: string; timeFrom?: string; timeTo?: string; reason?: string\n    }) {\n      if (!blockedMap[date]) blockedMap[date] = { allDay: false, slots: [], timeRanges: [], reason: data.reason }\n      if (data.allDay) { blockedMap[date].allDay = true; blockedMap[date].reason = data.reason }\n      if (data.slot)   blockedMap[date].slots.push(data.slot)\n      if (data.timeFrom && data.timeTo)\n        blockedMap[date].timeRanges.push({ from: data.timeFrom, to: data.timeTo })\n    }\n\n    for (const bl of blockedRes.data ?? []) {\n      if (bl.date_from && bl.date_to) {\n        // Expandir rango\n        const cur = new Date(bl.date_from)\n        const end = new Date(bl.date_to)\n        while (cur <= end) {\n          const dk = cur.toISOString().split('T')[0]\n          addBlocked(dk, { allDay: !bl.time_from, slot: bl.time_slot, timeFrom: bl.time_from, timeTo: bl.time_to, reason: bl.reason })\n          cur.setDate(cur.getDate() + 1)\n        }\n      } else if (bl.date) {\n        addBlocked(bl.date, { allDay: !bl.time_slot && !bl.time_from, slot: bl.time_slot, timeFrom: bl.time_from, timeTo: bl.time_to, reason: bl.reason })\n      }\n    }\n\n    // ── Días cerrados del negocio ──\n    const closedDays: string[] = []\n    for (const c of closedRes.data ?? []) {\n      if (c.date_from && c.date_to) {\n        const cur = new Date(c.date_from)\n        const end = new Date(c.date_to)\n        while (cur <= end) {\n          closedDays.push(cur.toISOString().split('T')[0])\n          cur.setDate(cur.getDate() + 1)\n        }\n      } else if (c.date) {\n        closedDays.push(c.date)\n      }\n    }\n\n    // También marcar días cerrados como bloqueados\n    for (const dk of closedDays) {\n      if (!blockedMap[dk]) blockedMap[dk] = { allDay: false, slots: [], timeRanges: [], reason: 'Cerrado' }\n      blockedMap[dk].allDay = true\n    }\n\n    // ── Horarios del barbero ──\n    // Marcar como bloqueados los días que el barbero no trabaja\n    if (staffId && schedulesRes.data && schedulesRes.data.length > 0) {\n      // Para cada día en el rango\n      const cur = new Date(from)\n      const end = new Date(to)\n      while (cur <= end) {\n        const dayOfWeek = cur.getDay() // 0=Dom\n        const dk = cur.toISOString().split('T')[0]\n        const schedule = (schedulesRes.data as {day_of_week:number;is_working:boolean}[]).find(s => s.day_of_week === dayOfWeek)\n        if (schedule && !schedule.is_working) {\n          if (!blockedMap[dk]) blockedMap[dk] = { allDay: false, slots: [], timeRanges: [], reason: 'No trabaja' }\n          blockedMap[dk].allDay = true\n          blockedMap[dk].reason = blockedMap[dk].reason === 'No trabaja' ? 'No trabaja' : blockedMap[dk].reason\n        }\n        cur.setDate(cur.getDate() + 1)\n      }\n    }\n\n    return NextResponse.json({\n      booked:    bookedMap,\n      blocked:   blockedMap,\n      closedDays,\n      schedules: schedulesRes.data ?? [],\n    })\n  } catch (err) {\n    console.error('[availability]', err)\n    return NextResponse.json({ booked: {}, blocked: {}, closedDays: [], schedules: [] })\n  }\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  OK ' + p)
}
